shell_commands_self_reported.command:
mkdir -p out && for f in $(find samples -type f | sort); do
case "$f" in
  *.html) t=$(sed -e 's/<[^>]*>/ /g' "$f") ;;
  *.md)   t=$(awk 'BEGIN{fm=0} NR==1&&/^---$/{fm=1;next} fm&&/^---$/{fm=0;next} !fm' "$f" | sed -e 's/^[#[:space:]]*//' -e 's/^[-*] //') ;;
  *)      t=$(cat "$f") ;;
esac
w=$(print
